from collections import deque
import math

# Globals for board geometry and caching
_initialized = False
_valid_mask = None
_N = 0
_valid_cells = []
_valid_set = set()
_neighbors = dict()        # cell -> list of neighbor cells
_edge_dirs = dict()        # cell -> list of edge direction indices where neighbor is invalid
_corner_index = dict()     # cell -> corner id (0..5)
_boundary_cells = set()    # valid cells on boundary (having any missing neighbor)
_center = (0.0, 0.0)
_max_dist = 0.0

# Hex directions in axial-like coords (r,c) for neighbor deltas
_DIRS = [(-1,0),(1,0),(0,-1),(-1,-1),(0,1),(-1,1)]

def init(valid_mask):
    global _initialized, _valid_mask, _N, _valid_cells, _valid_set
    global _neighbors, _edge_dirs, _corner_index, _boundary_cells, _center, _max_dist

    if _initialized and _valid_mask is valid_mask:
        return
    _valid_mask = valid_mask
    _N = len(valid_mask)
    _valid_cells = [(r,c) for r in range(_N) for c in range(_N) if valid_mask[r][c]]
    _valid_set = set(_valid_cells)

    # Compute neighbors and edge directions
    _neighbors = {}
    _edge_dirs = {}
    for cell in _valid_cells:
        r,c = cell
        neighbs = []
        edges = []
        for i,(dr,dc) in enumerate(_DIRS):
            nr,nc = r+dr, c+dc
            if 0 <= nr < _N and 0 <= nc < _N and valid_mask[nr][nc]:
                neighbs.append((nr,nc))
            else:
                edges.append(i)
        _neighbors[cell] = neighbs
        _edge_dirs[cell] = edges

    # Identify corners: cells with exactly 3 valid neighbors
    _corner_index = {}
    corner_id = 0
    for cell in _valid_cells:
        if len(_neighbors[cell]) == 3:
            _corner_index[cell] = corner_id
            corner_id += 1

    # Boundary cells: any valid cell with at least one missing neighbor
    _boundary_cells = {cell for cell in _valid_cells if _edge_dirs[cell]}

    # Compute center and max distance for heuristic
    sum_r = sum(c[0] for c in _valid_cells)
    sum_c = sum(c[1] for c in _valid_cells)
    count = len(_valid_cells)
    _center = (sum_r / count, sum_c / count)

    def dist_sq(cell):
        return (cell[0]-_center[0])**2 + (cell[1]-_center[1])**2
    _max_dist = max(dist_sq(cell) for cell in _valid_cells)

    _initialized = True

def analyze_components(stones_set):
    visited = set()
    comp_id = {}
    comp_edges = []
    comp_corners = []

    for cell in stones_set:
        if cell not in visited:
            queue = [cell]
            visited.add(cell)
            idx = len(comp_edges)
            edges = set()
            corners = set()
            while queue:
                v = queue.pop()
                comp_id[v] = idx
                if v in _corner_index:
                    corners.add(_corner_index[v])
                else:
                    for d in _edge_dirs.get(v, []):
                        edges.add(d)
                for nb in _neighbors.get(v, []):
                    if nb in stones_set and nb not in visited:
                        visited.add(nb)
                        queue.append(nb)
            comp_edges.append(edges)
            comp_corners.append(corners)
    return comp_id, comp_edges, comp_corners

def has_ring(stones_set):
    # Flood fill non-player cells from boundary; any unreachable non-player cell means ring
    nonplayer_cells = _valid_set - stones_set
    if not nonplayer_cells:
        return False
    visited = set()
    queue = deque()
    # Start BFS from boundary non-player cells
    for cell in _boundary_cells:
        if cell not in stones_set:
            visited.add(cell)
            queue.append(cell)
    while queue:
        cell = queue.popleft()
        for nb in _neighbors[cell]:
            if nb not in stones_set and nb not in visited:
                visited.add(nb)
                queue.append(nb)
    return len(visited) < len(nonplayer_cells)

def check_win(stones_set):
    visited = set()
    stones_list = list(stones_set)
    for cell in stones_list:
        if cell not in visited:
            queue = [cell]
            visited.add(cell)
            comp_cells = []
            edges = set()
            corners = set()
            while queue:
                v = queue.pop()
                comp_cells.append(v)
                if v in _corner_index:
                    corners.add(_corner_index[v])
                else:
                    for d in _edge_dirs.get(v, []):
                        edges.add(d)
                for nb in _neighbors.get(v, []):
                    if nb in stones_set and nb not in visited:
                        visited.add(nb)
                        queue.append(nb)
            if len(corners) >= 2:
                return True  # Bridge
            if len(edges) >= 3:
                return True  # Fork
    if has_ring(stones_set):
        return True
    return False

def evaluate_move(move, me_set, opp_set, comp_id, comp_edges, comp_corners):
    r,c = move
    neighbors_me = sum(1 for nb in _neighbors.get(move, []) if nb in me_set)
    neighbors_opp = sum(1 for nb in _neighbors.get(move, []) if nb in opp_set)

    adjacent_comps = set()
    for nb in _neighbors.get(move, []):
        if nb in comp_id:
            adjacent_comps.add(comp_id[nb])

    edges_union = set()
    corners_union = set()
    for cid in adjacent_comps:
        edges_union |= comp_edges[cid]
        corners_union |= comp_corners[cid]

    if move in _corner_index:
        corners_union.add(_corner_index[move])
    else:
        for d in _edge_dirs.get(move, []):
            edges_union.add(d)

    score = 0.0
    score += 2.0 * neighbors_me
    score += 0.5 * neighbors_opp
    if len(adjacent_comps) > 1:
        score += 3.0
    score += 1.5 * len(edges_union)
    score += 2.5 * len(corners_union)

    dist_sq = (r - _center[0])**2 + (c - _center[1])**2
    score += ( _max_dist - dist_sq ) * 0.1

    if move in _corner_index:
        score += 0.5
    elif _edge_dirs.get(move):
        score += 0.3

    return score

def policy(me, opp, valid_mask):
    init(valid_mask)
    me_set = set(me)
    opp_set = set(opp)
    occupied = me_set | opp_set
    legal_moves = [cell for cell in _valid_cells if cell not in occupied]
    if not legal_moves:
        # fallback if no legal move; should not happen
        return (0,0)

    # Immediate win attempt
    for move in legal_moves:
        if check_win(me_set | {move}):
            return move

    # Block opponent immediate win
    for move in legal_moves:
        if check_win(opp_set | {move}):
            return move

    # Analyze me components once for heuristic
    comp_id, comp_edges, comp_corners = analyze_components(me_set)

    # Evaluate moves heuristically
    best_move = None
    best_score = -float("inf")
    for move in legal_moves:
        score = evaluate_move(move, me_set, opp_set, comp_id, comp_edges, comp_corners)
        if score > best_score:
            best_score = score
            best_move = move

    return best_move
